with gaps as (select *, case when lag(txn_time) over (partition by merchant order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by merchant order by txn_time, id) + interval '60' day then 1 else 0 end as session_start_flag from transactions), islands as (select *, sum(session_start_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as session_id from gaps) select id, amount, is_flagged, session_id from islands order by session_id desc;
